      const tableMarkdown =
        chunk.blocks.find(
          (block) =>
            block.kind === "table" &&
            sourceLine >= block.blockStartLine &&
            sourceLine <= block.blockEndLine
        )?.markdown ?? ""
      return (
        <div
          className={`group relative my-3 overflow-x-auto rounded-lg border${highlightedClassName(node)}`}
          data-source-line={sourceLine}
