    td: ({ node: _node, ...props }) => (
      <td
        className="border-b border-border px-3 py-1.5 align-top tabular-nums [&[align=right]]:text-right"
        {...props}
      />
    ),
    th: ({ node: _node, ...props }) => (
      <th
        className="border-b border-border px-3 py-1.5 text-left font-medium [&[align=right]]:text-right"
        scope="col"
        {...props}
      />
    ),
    thead: ({ node: _node, ...props }) => (
      <thead className="bg-muted/60" {...props} />
    ),
    tr: ({ node: _node, ...props }) => <tr {...props} />,
    ul: ({ node, ...props }) => (
      <ul
        className={`my-2 ml-5 list-disc space-y-1${highlightedClassName(node)}`}
        data-source-line={sourceLineFromNode(node)}
        {...props}
      />
    ),
  }
}

function MarkdownDiagram({
  className,
  source,
  sourceLine,
}: {
  className: string
  source: string
  sourceLine: number
}) {
  const immediateState = React.useMemo(
    () => renderBasicMermaidDiagram(source),
    [source]
  )
  const [state, setState] = React.useState<
    | { status: "failed"; message: string }
    | { status: "ready"; svg: string }
    | { status: "unavailable" }
  >(immediateState)
  const diagramId = React.useId().replace(/:/g, "")

  React.useLayoutEffect(() => {
    setState(immediateState)
  }, [immediateState])

  React.useEffect(() => {
    let isMounted = true
    void renderMermaidDiagram(source, `markdown-diagram-${diagramId}`).then(
      (result) => {
        if (isMounted) setState(result)
      }
    )
    return () => {
      isMounted = false
    }
  }, [diagramId, source])

  return (
    <figure
      className={`my-3 min-h-40 overflow-hidden rounded-lg border bg-muted/30${className}`}
      data-diagram-language="mermaid"
      data-diagram-state={state.status}
      data-source-line={sourceLine}
    >
      <div className="flex h-8 items-center gap-2 border-b bg-muted/60 px-3">
        <span className="text-xs font-medium text-muted-foreground">
          mermaid
        </span>
        <MarkdownCodeCopyButton text={source} />
      </div>
      {state.status === "ready" ? (
        <div
          className="overflow-x-auto p-3"
          dangerouslySetInnerHTML={{ __html: state.svg }}
        />
      ) : (
        <pre className="overflow-x-auto p-3 font-mono text-[0.82em] leading-relaxed text-muted-foreground">
          {state.status === "failed"
            ? state.message
            : source}
        </pre>
      )}
    </figure>
  )
}

async function renderMermaidDiagram(source: string, id: string): Promise<
  | { status: "failed"; message: string }
  | { status: "ready"; svg: string }
> {
  try {
    const loadMermaid = new Function(
      "specifier",
      "return import(specifier)"
    ) as (specifier: string) => Promise<{
      default?: {
        initialize?: (options: Record<string, unknown>) => void
        render?: (id: string, source: string) => Promise<{ svg: string }>
      }
    }>
    const mermaidModule = await loadMermaid("mermaid")
    const mermaid = mermaidModule.default
    if (!mermaid?.render) return renderBasicMermaidDiagram(source)

    mermaid.initialize?.({
      securityLevel: "strict",
      startOnLoad: false,
      theme: "default",
    })
    const result = await mermaid.render(id, source)
    return { status: "ready", svg: result.svg }
  } catch (error) {
    const message = error instanceof Error ? error.message : "Invalid diagram"
    return message.includes("Cannot find") || message.includes("module")
      ? renderBasicMermaidDiagram(source)
      : { status: "failed", message }
  }
}

function renderBasicMermaidDiagram(
  source: string
): { status: "failed"; message: string } | { status: "ready"; svg: string } {
  const lines = source
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("%%"))
  const header = lines[0]?.match(/^(?:graph|flowchart)\s+(TD|TB|BT|LR|RL)$/i)
  if (!header) {
    return {
      status: "failed",
      message: "Unsupported Mermaid diagram. Only graph/flowchart diagrams are rendered.",
    }
  }

  const direction = header[1]!.toUpperCase()
  const edges: Array<{ from: string; to: string }> = []
  const labels = new Map<string, string>()

  for (const line of lines.slice(1)) {
    const edge = line.match(/^(.+?)\s*(?:-->|---|==>|-.->)\s*(.+?)$/)
    if (!edge) continue
    const from = parseMermaidNode(edge[1]!)
    const to = parseMermaidNode(edge[2]!)
    labels.set(from.id, from.label)
    labels.set(to.id, to.label)
    edges.push({ from: from.id, to: to.id })
  }

  if (edges.length === 0) {
    return {
      status: "failed",
      message: "Unsupported Mermaid diagram. Add at least one graph edge.",
    }
  }

  const nodeIds = Array.from(labels.keys())
  const isHorizontal = direction === "LR" || direction === "RL"
  const nodeWidth = 132
  const nodeHeight = 42
  const gap = 56
  const width = isHorizontal
    ? nodeIds.length * nodeWidth + Math.max(0, nodeIds.length - 1) * gap + 48
    : 420
  const height = isHorizontal
    ? 132
    : nodeIds.length * nodeHeight + Math.max(0, nodeIds.length - 1) * gap + 48
  const positions = new Map(
    nodeIds.map((nodeId, index) => {
      const orderedIndex =
        direction === "RL" || direction === "BT"
          ? nodeIds.length - index - 1
          : index
      return [
        nodeId,
        {
          x: isHorizontal
            ? 24 + orderedIndex * (nodeWidth + gap)
            : (width - nodeWidth) / 2,
          y: isHorizontal
            ? (height - nodeHeight) / 2
            : 24 + orderedIndex * (nodeHeight + gap),
        },
      ] as const
    })
  )

  const edgeSvg = edges
    .map((edge) => {
      const from = positions.get(edge.from)!
      const to = positions.get(edge.to)!
      const x1 = isHorizontal ? from.x + nodeWidth : from.x + nodeWidth / 2
      const y1 = isHorizontal ? from.y + nodeHeight / 2 : from.y + nodeHeight
      const x2 = isHorizontal ? to.x : to.x + nodeWidth / 2
      const y2 = isHorizontal ? to.y + nodeHeight / 2 : to.y
      return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="currentColor" stroke-width="1.5" marker-end="url(#arrow)" opacity="0.65" />`
    })
    .join("")
  const nodeSvg = nodeIds
    .map((nodeId) => {
      const position = positions.get(nodeId)!
      return `<g><rect x="${position.x}" y="${position.y}" width="${nodeWidth}" height="${nodeHeight}" rx="8" fill="var(--card)" stroke="currentColor" opacity="0.9" /><text x="${position.x + nodeWidth / 2}" y="${position.y + 26}" text-anchor="middle" font-size="13" fill="currentColor">${escapeSvg(labels.get(nodeId) ?? nodeId)}</text></g>`
    })
    .join("")

  return {
    status: "ready",
    svg: `<svg role="img" aria-label="Mermaid diagram" viewBox="0 0 ${width} ${height}" width="100%" height="${height}" xmlns="http://www.w3.org/2000/svg"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="currentColor" opacity="0.65"/></marker></defs>${edgeSvg}${nodeSvg}</svg>`,
  }
}

function parseMermaidNode(value: string) {
  const trimmed = value.trim()
  const match =
    trimmed.match(/^([A-Za-z0-9_-]+)\s*\["(.+)"\]$/) ??
    trimmed.match(/^([A-Za-z0-9_-]+)\s*\[(.+)\]$/) ??
    trimmed.match(/^([A-Za-z0-9_-]+)\s*\((.+)\)$/)
  if (match) {
    return { id: match[1]!, label: match[2]!.trim() }
  }

  const id = trimmed.replace(/[^A-Za-z0-9_-].*$/, "")
  return { id: id || trimmed, label: id || trimmed }
}

function escapeSvg(value: string) {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
}

function MarkdownImage({
  alt,
  className,
  sourceLine,
  src,
  title,
  ...props
}: React.ImgHTMLAttributes<HTMLImageElement> & {
  sourceLine: number
}) {
  const [status, setStatus] = React.useState<"failed" | "idle">("idle")
  const safeSrc = typeof src === "string" ? sanitizeMarkdownImageUrl(src) : ""
  const label = alt || safeSrc || "Markdown image"

  if (!safeSrc || status === "failed") {
    return (
      <span
        className={`my-3 flex min-h-20 items-center rounded-lg border bg-muted/40 px-4 text-sm text-muted-foreground ${className}`}
        data-image-state={safeSrc ? "failed" : "blocked"}
        data-source-line={sourceLine}
        role="img"
        aria-label={label}
      >
        {label}
      </span>
    )
  }

  return (
    <img
      alt={alt}
      className={`my-3 max-h-[480px] rounded-lg border bg-muted object-contain ${className}`}
      data-image-state="idle"
      data-source-line={sourceLine}
      src={safeSrc}
      title={title}
      onError={() => setStatus("failed")}
      {...props}
    />
  )
}

function headingIdForNode({
  headingIdsByLine,
  node,
  chunk,
}: {
  headingIdsByLine: ReadonlyMap<number, string>
  node: unknown
  chunk: MarkdownDocumentChunk
}) {
  return headingIdsByLine.get(
    absoluteSourceLine(chunk, relativeSourceLine(node))
  )
}

function nextHeadingId(text: string, registry: Map<string, number>) {
  const base = slugifyHeading(text) || "section"
  const count = registry.get(base) ?? 0
  registry.set(base, count + 1)
  return count === 0 ? base : `${base}-${count}`
}

function slugifyHeading(text: string) {
  return text
    .toLowerCase()
    .replace(/<[^>]*>/g, "")
    .replace(/[^\p{Letter}\p{Number}_\s-]/gu, "")
    .trim()
    .replace(/\s+/g, "-")
}

function relativeSourceLine(node: unknown) {
  const position = (node as { position?: { start?: { line?: number } } })
    ?.position
  const line = position?.start?.line
  return Number.isFinite(line) && line ? line : 1
}

function absoluteSourceLine(chunk: MarkdownDocumentChunk, relativeLine: number) {
  return (
    chunk.sourceLineByRenderedLine?.get(relativeLine) ??
    chunk.chunkStartLine + relativeLine - 1
  )
}

function isSourceLineHighlighted(
  sourceLine: number,
  range: MarkdownLineRange | null
) {
  return Boolean(range && sourceLine >= range.start && sourceLine <= range.end)
}

function extractReactText(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(extractReactText).join("")
  if (React.isValidElement<{ children?: React.ReactNode }>(node)) {
    return extractReactText(node.props.children)
  }
  return ""
}

function codeLanguage(node: React.ReactNode): string | null {
  if (
    !React.isValidElement<{
      className?: string
      "data-language"?: string
    }>(node)
  ) {
    if (Array.isArray(node)) return node.map(codeLanguage).find(Boolean) ?? null
    return null
  }
  const className = node.props.className ?? ""
  return (
    node.props["data-language"] ??
    className.match(/language-([^\s]+)/)?.[1] ??
    null
  )
}

"use client"

import * as React from "react"
import type { Node } from "unist"
import { visit } from "unist-util-visit"

type MarkdownComponentName =
  | "accordion"
  | "accordion-item"
  | "badge"
  | "callout"
  | "diagram"
  | "image"
  | "metric"
  | "tab"
  | "tabs"
  | "unknown"
  | "video"

const COMPONENT_NAMES = new Set<MarkdownComponentName>([
  "accordion",
  "accordion-item",
  "badge",
  "callout",
  "diagram",
  "image",
  "metric",
  "tab",
  "tabs",
  "unknown",
  "video",
])

const HTML_ELEMENT_NAMES = new Set([
  "a",
  "abbr",
  "b",
  "blockquote",
  "br",
  "button",
  "caption",
  "cite",
  "code",
  "dd",
  "del",
  "details",
  "div",
  "dl",
  "dt",
  "em",
  "figcaption",
  "figure",
  "h1",
  "h2",
  "h3",
  "h4",
  "h5",
  "h6",
  "hr",
  "i",
  "iframe",
  "img",
  "input",
  "ins",
  "kbd",
  "li",
  "mark",
  "ol",
  "p",
  "pre",
  "q",
  "rp",
  "rt",
  "ruby",
  "s",
  "script",
  "section",
  "span",
  "strong",
  "style",
  "sub",
  "summary",
  "sup",
  "table",
  "tbody",
  "td",
  "th",
  "thead",
  "tr",
  "ul",
])

export function remarkMarkdownComponents() {
  return (tree: unknown) => {
    visit(
      tree as Node,
      ["containerDirective", "leafDirective", "textDirective"],
      (visitedNode) => {
        const node = visitedNode as {
          attributes?: Record<string, unknown>
          data?: Record<string, unknown>
          name?: string
        }
        const componentName = normalizeMarkdownComponentName(node.name)
        if (!componentName) return

        node.data ??= {}
        node.data.hName = "div"
        node.data.hProperties = markdownComponentProperties({
          attributes: node.attributes,
          name: componentName,
        })
      }
    )
  }
}

export function rehypeMarkdownComponents() {
  return (tree: unknown) => {
    visit(tree as Node, "element", (visitedNode) => {
      const node = visitedNode as {
        properties?: Record<string, unknown>
        tagName?: string
      }
      const componentName = normalizeMarkdownComponentName(node.tagName)
      if (!componentName && !isUnknownMarkdownComponentTag(node.tagName)) return
      const originalName = node.tagName

      node.tagName = "div"
      node.properties = markdownComponentProperties({
        attributes: node.properties,
        name: componentName ?? "unknown",
        originalName,
      })
    })
  }
}

export function markdownComponentNameFromProps(props: Record<string, unknown>) {
  return normalizeMarkdownComponentName(props["data-component-name"])
}

export function MarkdownComponent({
  children,
  name,
  props,
  sourceLine,
}: {
  children: React.ReactNode
  name: MarkdownComponentName
  props: Record<string, unknown>
  sourceLine: number
}) {
  switch (name) {
    case "badge":
      return (
        <span
          className="inline-flex items-center rounded-md border bg-muted px-1.5 py-0.5 text-[0.78em] font-medium"
          data-component-name={name}
          data-source-line={sourceLine}
        >
          {componentText(props, "label") || children}
        </span>
      )
    case "metric":
      return (
        <div
          className="my-3 grid max-w-sm grid-cols-[1fr_auto] gap-3 rounded-lg border bg-muted/30 px-3 py-2"
          data-component-name={name}
          data-source-line={sourceLine}
        >
          <span className="text-sm text-muted-foreground">
            {componentText(props, "label") || "Metric"}
          </span>
          <span className="font-mono text-sm font-semibold">
            {componentText(props, "value") || children || "-"}
          </span>
        </div>
      )
    case "tabs":
    case "tab":
    case "accordion":
    case "accordion-item":
      return (
        <div
          className="my-3 rounded-lg border bg-muted/20 px-3 py-2"
          data-component-name={name}
          data-source-line={sourceLine}
        >
          <div className="mb-1 text-xs font-medium uppercase tracking-wide text-muted-foreground">
            {componentText(props, "label") || componentText(props, "title") || name}
          </div>
          <div className="[&>:first-child]:mt-0 [&>:last-child]:mb-0">
            {children}
          </div>
        </div>
      )
    case "callout":
    case "diagram":
    case "image":
    case "video":
      return (
        <div
          className="my-3 rounded-lg border bg-muted/20 px-3 py-2"
          data-component-name={name}
          data-source-line={sourceLine}
        >
          <div className="mb-1 text-sm font-semibold">
            {componentText(props, "title") || name}
          </div>
          <div className="[&>:first-child]:mt-0 [&>:last-child]:mb-0">
            {children}
          </div>
        </div>
      )
    case "unknown":
      return (
        <span
          className="my-1 inline-flex flex-wrap items-baseline gap-1 rounded-md border border-dashed bg-muted/20 px-2 py-1 text-sm"
          data-component-name={name}
          data-source-line={sourceLine}
        >
          <span className="font-medium text-muted-foreground">
            Unsupported component
            {componentText(props, "source")
              ? `: ${componentText(props, "source")}`
              : null}
          </span>
          {children ? <span>{children}</span> : null}
        </span>
      )
  }
}

function markdownComponentProperties({
  attributes,
  name,
  originalName,
}: {
  attributes?: Record<string, unknown>
  name: MarkdownComponentName
  originalName?: string
}) {
  return {
    dataComponentKind: componentAttribute(attributes, "kind"),
    dataComponentLabel: componentAttribute(attributes, "label"),
    dataComponentName: name,
    dataComponentSource: originalName,
    dataComponentTitle: componentAttribute(attributes, "title"),
    dataComponentValue: componentAttribute(attributes, "value"),
  }
}

function componentAttribute(
  attributes: Record<string, unknown> | undefined,
  key: string
) {
  const value = attributes?.[key]
  return typeof value === "string" || typeof value === "number"
    ? String(value)
    : undefined
}

function componentText(props: Record<string, unknown>, key: string) {
  const value = props[`data-component-${key}`]
  return typeof value === "string" ? value : ""
}

function normalizeMarkdownComponentName(
  value: unknown
): MarkdownComponentName | null {
  const normalized = String(value ?? "").toLowerCase()
  return COMPONENT_NAMES.has(normalized as MarkdownComponentName)
    ? (normalized as MarkdownComponentName)
    : null
}

function isUnknownMarkdownComponentTag(value: unknown) {
  const normalized = String(value ?? "").toLowerCase()
  if (!normalized || HTML_ELEMENT_NAMES.has(normalized)) return false
  return /^[a-z][a-z0-9-]*$/.test(normalized)
}

"use client"

import * as React from "react"
import type { Node } from "unist"
import { visit } from "unist-util-visit"

export type MarkdownCalloutKind =
  | "caution"
  | "danger"
  | "important"
  | "info"
  | "note"
  | "tip"
  | "warning"

export function remarkMarkdownCallouts() {
  return (tree: unknown) => {
    transformGithubAlertBlockquotes(tree)
    visit(
      tree as Node,
      ["containerDirective", "leafDirective"],
      (visitedNode) => {
        const node = visitedNode as {
          attributes?: Record<string, unknown>
          data?: Record<string, unknown>
          name?: string
        }
        const calloutKind = normalizeMarkdownCalloutKind(node.name)
        if (!calloutKind) return

        const calloutTitle =
          typeof node.attributes?.title === "string"
            ? node.attributes.title
            : markdownCalloutLabel(calloutKind)

        node.data ??= {}
        node.data.hName = "div"
        node.data.hProperties = {
          dataCalloutKind: calloutKind,
          dataCalloutTitle: calloutTitle,
        }
      }
    )
  }
}

function transformGithubAlertBlockquotes(tree: unknown) {
  visit(tree as Node, "blockquote", (visitedNode) => {
    const node = visitedNode as {
      children?: Array<{
        children?: Array<{ type?: string; value?: string }>
        type?: string
      }>
      data?: Record<string, unknown>
    }
    const firstParagraph = node.children?.[0]
    const firstText = firstParagraph?.children?.[0]
    if (firstParagraph?.type !== "paragraph" || firstText?.type !== "text") {
      return
    }

    const marker = firstText.value?.match(/^\[!(\w+)\][ \t]*(?:\r?\n)?/)
    const calloutKind = normalizeMarkdownCalloutKind(marker?.[1])
    if (!marker || !calloutKind || !firstText.value) return

    firstText.value = firstText.value.slice(marker[0].length)
    if (firstText.value.length === 0) {
      firstParagraph.children?.shift()
    }
    if (firstParagraph.children?.length === 0) {
      node.children?.shift()
    }

    node.data ??= {}
    node.data.hName = "div"
    node.data.hProperties = {
      dataCalloutKind: calloutKind,
      dataCalloutTitle: markdownCalloutLabel(calloutKind),
    }
  })
}

export function MarkdownCallout({
  children,
  className,
  kind,
  sourceLine,
  title,
}: {
  children: React.ReactNode
  className: string
  kind: MarkdownCalloutKind
  sourceLine: number
  title: string
}) {
  return (
    <aside
      className={`my-3 rounded-lg border px-3 py-2.5 ${markdownCalloutClassName(kind)}${className}`}
      data-callout-kind={kind}
      data-source-line={sourceLine}
    >
      <div className="mb-1 text-sm font-semibold">{title}</div>
      <div className="[&>:first-child]:mt-0 [&>:last-child]:mb-0">
        {children}
      </div>
    </aside>
  )
}

export function normalizeMarkdownCalloutKind(
  value: unknown
): MarkdownCalloutKind | null {
  switch (String(value ?? "").toLowerCase()) {
    case "caution":
      return "caution"
    case "danger":
    case "error":
    case "failure":
      return "danger"
    case "important":
      return "important"
    case "info":
      return "info"
    case "note":
      return "note"
    case "success":
    case "tip":
      return "tip"
    case "warning":
      return "warning"
    default:
      return null
  }
}

export function markdownCalloutKindFromProps(props: Record<string, unknown>) {
  return normalizeMarkdownCalloutKind(props["data-callout-kind"])
}

export function markdownCalloutTitleFromProps(props: Record<string, unknown>) {
  const title = props["data-callout-title"]
  const calloutKind = markdownCalloutKindFromProps(props)
  return typeof title === "string" && title.trim()
    ? title
    : markdownCalloutLabel(calloutKind ?? "note")
}

export function markdownCalloutLabel(kind: MarkdownCalloutKind) {
  switch (kind) {
    case "caution":
      return "Caution"
    case "danger":
      return "Danger"
    case "important":
      return "Important"
    case "info":
      return "Info"
    case "note":
      return "Note"
    case "tip":
      return "Tip"
    case "warning":
      return "Warning"
  }
}

function markdownCalloutClassName(kind: MarkdownCalloutKind) {
  switch (kind) {
    case "caution":
      return "border-orange-200 bg-orange-50 text-orange-950 dark:border-orange-900/60 dark:bg-orange-950/25 dark:text-orange-100"
    case "danger":
      return "border-red-200 bg-red-50 text-red-950 dark:border-red-900/60 dark:bg-red-950/25 dark:text-red-100"
    case "important":
      return "border-violet-200 bg-violet-50 text-violet-950 dark:border-violet-900/60 dark:bg-violet-950/25 dark:text-violet-100"
    case "info":
      return "border-sky-200 bg-sky-50 text-sky-950 dark:border-sky-900/60 dark:bg-sky-950/25 dark:text-sky-100"
    case "note":
      return "border-border bg-muted/35 text-foreground"
    case "tip":
      return "border-emerald-200 bg-emerald-50 text-emerald-950 dark:border-emerald-900/60 dark:bg-emerald-950/25 dark:text-emerald-100"
    case "warning":
      return "border-amber-200 bg-amber-50 text-amber-950 dark:border-amber-900/60 dark:bg-amber-950/25 dark:text-amber-100"
  }
}

"use client"

import * as React from "react"
import { Check, Copy } from "lucide-react"

import { Button } from "./button"
import { serializeMarkdownTableForClipboard } from "./markdown-document-model"

type CopyStatus = "copied" | "idle"

export function MarkdownCodeCopyButton({ text }: { text: string }) {
  return (
    <MarkdownCopyButton
      ariaLabel="Copy code block"
      copiedLabel="Copied"
      className="ml-auto opacity-100 sm:opacity-0 sm:group-hover:opacity-100"
      text={text}
    />
  )
}

export function MarkdownTableCopyButton({ markdown }: { markdown: string }) {
  return (
    <MarkdownCopyButton
      ariaLabel="Copy table"
      copiedLabel="Copied"
      className="absolute top-2 right-2 z-10 opacity-100 sm:opacity-0 sm:group-hover:opacity-100"
      text={serializeMarkdownTableForClipboard(markdown)}
    />
  )
}

export function MarkdownCopyButton({
  ariaLabel,
  className,
  copiedLabel,
  text,
}: {
  ariaLabel: string
  className?: string
  copiedLabel: string
  text: string
}) {
  const [status, setStatus] = React.useState<CopyStatus>("idle")
  const timeoutRef = React.useRef<number | null>(null)

  React.useEffect(
    () => () => {
      if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current)
    },
    []
  )

  const copy = () => {
    if (timeoutRef.current !== null) window.clearTimeout(timeoutRef.current)
    void navigator.clipboard?.writeText(text).then(() => {
      setStatus("copied")
      timeoutRef.current = window.setTimeout(() => {
        timeoutRef.current = null
        setStatus("idle")
      }, 1200)
    })
  }

  return (
    <Button
      aria-label={status === "copied" ? copiedLabel : ariaLabel}
      className={className}
      size="icon-sm"
      title={ariaLabel}
      type="button"
      variant="ghost"
      onClick={copy}
    >
      {status === "copied" ? <Check /> : <Copy />}
    </Button>
  )
}

export function sanitizeMarkdownUrl(value: string) {
  const trimmed = value.trim()
  if (!trimmed) return ""
  if (trimmed.startsWith("#") || trimmed.startsWith("/")) return trimmed

  try {
    const url = new URL(trimmed, "https://retab.local")
    if (
      url.protocol === "http:" ||
      url.protocol === "https:" ||
      url.protocol === "mailto:"
    ) {
      return trimmed
    }
  } catch {
    return ""
  }

  return ""
}

export function sanitizeMarkdownImageUrl(value: string) {
  const safeUrl = sanitizeMarkdownUrl(value)
  if (!safeUrl || safeUrl.startsWith("mailto:") || safeUrl.startsWith("#")) {
    return ""
  }
  return safeUrl
}

import { marked, type Token, type Tokens } from "marked"

import {
  clampMarkdownChunkHeight,
  createEstimatedMarkdownBlock,
  MARKDOWN_DOCUMENT_TARGET_CHUNK_HEIGHT,
  chunkChromeHeight,
} from "./markdown-document-layout"
import { splitTextLines } from "./text-viewer-resource"

export type MarkdownDocumentBlockKind =
  | "blockquote"
  | "callout"
  | "code"
  | "heading"
  | "html"
  | "image"
  | "list"
  | "math"
  | "paragraph"
  | "rule"
  | "table"

export interface MarkdownDocumentBlock {
  blockEndLine: number
  blockStartLine: number
  estimatedHeight: number
  headingId: string | null
  id: string
  isHostile: boolean
  kind: MarkdownDocumentBlockKind
  markdown: string
}

export interface MarkdownDocumentChunk {
  blocks: MarkdownDocumentBlock[]
  estimatedHeight: number
  id: string
  markdown: string
  chunkEndLine: number
  chunkIndex: number
  chunkStartLine: number
  sourceText: string
  sourceLineByRenderedLine: ReadonlyMap<number, number>
}

export interface MarkdownDocument {
  blocks: MarkdownDocumentBlock[]
  headingIdsByLine: Map<number, string>
  lineCount: number
  chunks: MarkdownDocumentChunk[]
  text: string
  wordCount: number
}

export type MarkdownLineRange = {
  end: number
  start: number
}

type SourceToken = Token & {
  raw?: string
  text?: string
  tokens?: Token[]
}

type HeadingRegistry = Map<string, number>

export function createMarkdownDocument(text: string): MarkdownDocument {
  const normalizedText = text.length === 0 ? " " : text
  const headingRegistry: HeadingRegistry = new Map()
  const blocks = createMarkdownBlocks(normalizedText, headingRegistry)
  const chunks = createMarkdownChunks(blocks, normalizedText)
  const headingIdsByLine = new Map<number, string>()

  for (const block of blocks) {
    if (block.headingId) {
      headingIdsByLine.set(block.blockStartLine, block.headingId)
    }
  }

  return {
    blocks,
    headingIdsByLine,
    lineCount: splitTextLines(normalizedText).length,
    chunks,
    text: normalizedText,
    wordCount: countWords(normalizedText),
  }
}

export function findMarkdownChunkForLine(
  chunks: readonly MarkdownDocumentChunk[],
  sourceLine: number
) {
  return chunks.find(
    (chunk) => sourceLine >= chunk.chunkStartLine && sourceLine <= chunk.chunkEndLine
  )
}

export function markdownChunkIntersectsLineRange({
  chunk,
  range,
}: {
  chunk: MarkdownDocumentChunk
  range: MarkdownLineRange | null
}) {
  if (!range) return false
  return chunk.chunkStartLine <= range.end && chunk.chunkEndLine >= range.start
}

export function serializeMarkdownTableForClipboard(markdown: string) {
  const tableToken = marked
    .lexer(markdown, { gfm: true })
    .find((token): token is Tokens.Table => token.type === "table")
  if (!tableToken) return markdown.trim()

  const header = tableToken.header.map((cell) => cell.text.trim())
  const rows = tableToken.rows.map((row) => row.map((cell) => cell.text.trim()))
  return [header, ...rows].map((row) => row.join("\t")).join("\n")
}

function createMarkdownBlocks(
  text: string,
  headingRegistry: HeadingRegistry
): MarkdownDocumentBlock[] {
  const frontmatter = extractYamlFrontmatter(text)
  const blocks: MarkdownDocumentBlock[] = []

  if (frontmatter) {
    const estimatedBlock = createEstimatedMarkdownBlock({
      kind: "code",
      markdown: frontmatter.renderMarkdown,
    })
    blocks.push({
      blockEndLine: frontmatter.endLine,
      blockStartLine: 1,
      estimatedHeight: estimatedBlock.estimatedHeight,
      headingId: null,
      id: "block-1-frontmatter",
      isHostile: estimatedBlock.isHostile,
      kind: "code",
      markdown: frontmatter.renderMarkdown,
    })
  }

  const markdownText = frontmatter
    ? text.slice(frontmatter.markdown.length)
    : text
  const baseLine = frontmatter ? frontmatter.endLine + 1 : 1
  const tokens = marked.lexer(markdownText, { gfm: true })
  let cursorLine = baseLine
  let previousTokenWasBlock = false

  for (const token of tokens as SourceToken[]) {
    if (token.type === "space") {
      const rawLineCount = countRawLines(token.raw ?? "\n")
      cursorLine += previousTokenWasBlock
        ? Math.max(0, rawLineCount - 1)
        : rawLineCount
      continue
    }

    const raw = token.raw ?? tokenText(token)
    const blockStartLine = cursorLine
    const blockEndLine = Math.max(
      blockStartLine,
      blockStartLine + countRawLines(raw) - 1
    )
    const kind = markdownBlockKind(token, raw)
    const headingId =
      token.type === "heading"
        ? createHeadingId((token as Tokens.Heading).text, headingRegistry)
        : null
    const markdown = raw.trimEnd() || " "
    const estimatedBlock = createEstimatedMarkdownBlock({ kind, markdown })

    blocks.push({
      blockEndLine,
      blockStartLine,
      estimatedHeight: estimatedBlock.estimatedHeight,
      headingId,
      id: `block-${blocks.length + 1}-${blockStartLine}`,
      isHostile: estimatedBlock.isHostile,
      kind,
      markdown,
    })

    cursorLine = blockEndLine + 1
    previousTokenWasBlock = true
  }

  if (blocks.length === 0) {
    blocks.push({
      blockEndLine: 1,
      blockStartLine: 1,
      estimatedHeight: 120,
      headingId: null,
      id: "block-1-empty",
      isHostile: false,
      kind: "paragraph",
      markdown: " ",
    })
  }

  return blocks
}

function createMarkdownChunks(
  blocks: readonly MarkdownDocumentBlock[],
  text: string
): MarkdownDocumentChunk[] {
  const chunks: MarkdownDocumentChunk[] = []
  const sourceLineOffsets = createSourceLineOffsets(text)
  let currentBlocks: MarkdownDocumentBlock[] = []
  let currentHeight = chunkChromeHeight()

  const flush = () => {
    if (currentBlocks.length === 0) return
    const { markdown, sourceLineByRenderedLine } =
      createMarkdownChunkContent(currentBlocks)
    const chunkStartLine = currentBlocks[0]!.blockStartLine
    const chunkEndLine = currentBlocks[currentBlocks.length - 1]!.blockEndLine
    chunks.push({
      blocks: currentBlocks,
      estimatedHeight: clampMarkdownChunkHeight(currentHeight),
      id: `chunk-${chunks.length + 1}-${chunkStartLine}`,
      markdown,
      chunkEndLine,
      chunkIndex: chunks.length,
      chunkStartLine,
      sourceText: sourceTextForLineRange({
        endLine: chunkEndLine,
        lineOffsets: sourceLineOffsets,
        startLine: chunkStartLine,
        text,
      }),
      sourceLineByRenderedLine,
    })
    currentBlocks = []
    currentHeight = chunkChromeHeight()
  }

  for (let index = 0; index < blocks.length; index++) {
    const block = blocks[index]!
    const nextBlock = blocks[index + 1]
    const blockHeight = block.estimatedHeight

    if (block.isHostile) {
      flush()
      currentBlocks.push(block)
      currentHeight += blockHeight
      flush()
      continue
    }

    const shouldKeepHeadingWithNext =
      block.kind === "heading" &&
      nextBlock &&
      currentHeight + blockHeight + nextBlock.estimatedHeight <=
        MARKDOWN_DOCUMENT_TARGET_CHUNK_HEIGHT

    if (
      currentBlocks.length > 0 &&
      !shouldKeepHeadingWithNext &&
      currentHeight + blockHeight > MARKDOWN_DOCUMENT_TARGET_CHUNK_HEIGHT
    ) {
      flush()
    }

    currentBlocks.push(block)
    currentHeight += blockHeight

    if (
      currentHeight > MARKDOWN_DOCUMENT_TARGET_CHUNK_HEIGHT &&
      isOversizedBlock(block)
    ) {
      flush()
    }
  }

  flush()
  return chunks
}

function createMarkdownChunkContent(blocks: readonly MarkdownDocumentBlock[]): {
  markdown: string
  sourceLineByRenderedLine: ReadonlyMap<number, number>
} {
  const sourceLineByRenderedLine = new Map<number, number>()
  const parts: string[] = []
  let renderedLine = 1

  for (const block of blocks) {
    if (parts.length > 0) {
      parts.push("")
      renderedLine += 1
    }

    parts.push(block.markdown)
    const blockLines = splitTextLines(block.markdown)
    for (let index = 0; index < blockLines.length; index++) {
      sourceLineByRenderedLine.set(
        renderedLine + index,
        Math.min(block.blockEndLine, block.blockStartLine + index)
      )
    }
    renderedLine += blockLines.length
  }

  return {
    markdown: parts.join("\n"),
    sourceLineByRenderedLine,
  }
}

function createSourceLineOffsets(text: string) {
  const offsets = [0]
  for (const match of text.matchAll(/\r\n|[\n\r\u2028\u2029]/g)) {
    offsets.push(match.index + match[0].length)
  }
  offsets.push(text.length)
  return offsets
}

function sourceTextForLineRange({
  endLine,
  lineOffsets,
  startLine,
  text,
}: {
  endLine: number
  lineOffsets: readonly number[]
  startLine: number
  text: string
}) {
  const safeStartLine = Math.max(1, startLine)
  const safeEndLine = Math.max(safeStartLine, endLine)
  const startOffset = lineOffsets[safeStartLine - 1] ?? 0
  let endOffset = lineOffsets[safeEndLine] ?? text.length

  while (endOffset > startOffset && /[\n\r\u2028\u2029]/.test(text[endOffset - 1]!)) {
    endOffset -= 1
  }

  return text.slice(startOffset, endOffset)
}

function extractYamlFrontmatter(text: string) {
  const match = text.match(/^---(?:\r?\n)([\s\S]*?)(?:\r?\n)---(?:\r?\n|$)/)
  if (!match) return null

  const markdown = match[0]
  const inner = match[1] ?? ""
  return {
    endLine: countRawLines(markdown),
    markdown,
    renderMarkdown: ["```yaml", inner.trimEnd(), "```"].join("\n"),
  }
}

function markdownBlockKind(
  token: Token,
  raw: string
): MarkdownDocumentBlockKind {
  if (isDirectiveBlock(raw)) return "callout"
  if (isMathBlock(raw)) return "math"

  switch (token.type) {
    case "blockquote":
      return "blockquote"
    case "code":
      return "code"
    case "heading":
      return "heading"
    case "html":
      return "html"
    case "list":
      return "list"
    case "hr":
      return "rule"
    case "table":
      return "table"
    case "paragraph": {
      const paragraph = token as Tokens.Paragraph
      return paragraph.tokens?.length === 1 &&
        paragraph.tokens[0]?.type === "image"
        ? "image"
        : "paragraph"
    }
    default:
      return "paragraph"
  }
}

function isDirectiveBlock(raw: string) {
  return /^:::(?:note|info|tip|success|warning|caution|danger|error|failure)\b/im.test(
    raw.trimStart()
  )
}

function isMathBlock(raw: string) {
  return /^\$\$[\s\S]*\$\$\s*$/.test(raw.trim())
}

function isOversizedBlock(block: MarkdownDocumentBlock) {
  return block.estimatedHeight > MARKDOWN_DOCUMENT_TARGET_CHUNK_HEIGHT * 0.8
}

function createHeadingId(text: string, registry: HeadingRegistry) {
  const base = slugifyHeading(text) || "section"
  let count = registry.get(base) ?? 0
  let candidate = count === 0 ? base : `${base}-${count}`

  while (registry.has(candidate)) {
    count += 1
    candidate = `${base}-${count}`
  }

  registry.set(base, count + 1)
  if (candidate !== base) {
    registry.set(candidate, 1)
  }
  return candidate
}

function slugifyHeading(text: string) {
  return text
    .toLowerCase()
    .replace(/<[^>]*>/g, "")
    .replace(/[^\p{Letter}\p{Number}_\s-]/gu, "")
    .trim()
    .replace(/\s+/g, "-")
}

function countRawLines(raw: string) {
  return splitTextLines(raw.replace(/\r?\n$/, "")).length
}

function tokenText(token: SourceToken) {
  return typeof token.text === "string" ? token.text : (token.raw ?? "")
}

function countWords(text: string) {
  return text.trim().split(/\s+/).filter(Boolean).length
}

export interface MarkdownVirtualItem {
  bottom: number
  height: number
  index: number
  key: string
  top: number
}

export interface MarkdownVirtualGeometry {
  count: number
  heights: readonly number[]
  keys: readonly string[]
  offsets: readonly number[]
  totalHeight: number
}

export interface MarkdownScrollAnchor {
  index: number
  offsetWithinItem: number
}

export function createMarkdownVirtualGeometry({
  count,
  estimateHeight,
  getKey,
  measuredHeights,
}: {
  count: number
  estimateHeight: (index: number) => number
  getKey: (index: number) => string
  measuredHeights: ReadonlyMap<string, number>
}): MarkdownVirtualGeometry {
  const heights: number[] = []
  const keys: string[] = []
  const offsets = [0]

  for (let index = 0; index < count; index++) {
    const key = getKey(index)
    const height = resolveMarkdownItemHeight({
      estimateHeight,
      index,
      key,
      measuredHeights,
    })
    keys.push(key)
    heights.push(height)
    offsets.push(offsets[index]! + height)
  }

  return {
    count,
    heights,
    keys,
    offsets,
    totalHeight: offsets[count] ?? 0,
  }
}

export function getMarkdownVirtualItems({
  geometry,
  overscanPx,
  scrollTop,
  viewportHeight,
}: {
  geometry: MarkdownVirtualGeometry
  overscanPx: number
  scrollTop: number
  viewportHeight: number
}): {
  items: MarkdownVirtualItem[]
  totalHeight: number
} {
  if (geometry.count === 0) {
    return { items: [], totalHeight: 0 }
  }

  const items: MarkdownVirtualItem[] = []
  const viewportTop = Math.max(0, scrollTop - overscanPx)
  const viewportBottom = scrollTop + viewportHeight + overscanPx
  const startIndex = findFirstItemWithBottomAtOrAfter(
    geometry.offsets,
    viewportTop
  )
  const endIndex = findFirstItemWithTopAfter(geometry.offsets, viewportBottom)

  for (let index = startIndex; index < endIndex; index++) {
    const top = geometry.offsets[index]!
    const bottom = geometry.offsets[index + 1]!
    items.push({
      bottom,
      height: geometry.heights[index]!,
      index,
      key: geometry.keys[index]!,
      top,
    })
  }

  return { items, totalHeight: geometry.totalHeight }
}

export function getMarkdownScrollAnchor({
  geometry,
  scrollTop,
}: {
  geometry: MarkdownVirtualGeometry
  scrollTop: number
}): MarkdownScrollAnchor | null {
  if (geometry.count === 0) return null

  const index = Math.min(
    findFirstItemWithBottomAtOrAfter(geometry.offsets, scrollTop),
    geometry.count - 1
  )
  return {
    index,
    offsetWithinItem: Math.max(0, scrollTop - geometry.offsets[index]!),
  }
}

export function scrollTopForMarkdownAnchor({
  anchor,
  geometry,
}: {
  anchor: MarkdownScrollAnchor
  geometry: MarkdownVirtualGeometry
}) {
  if (geometry.count === 0) return 0

  const targetIndex = Math.min(Math.max(0, anchor.index), geometry.count - 1)
  const targetHeight = geometry.heights[targetIndex]!
  return Math.max(
    0,
    geometry.offsets[targetIndex]! +
      Math.min(anchor.offsetWithinItem, Math.max(0, targetHeight - 1))
  )
}

export function topForMarkdownIndex({
  geometry,
  index,
}: {
  geometry: MarkdownVirtualGeometry
  index: number
}) {
  if (geometry.count === 0) return 0

  const targetIndex = Math.min(Math.max(0, index), geometry.count - 1)
  return geometry.offsets[targetIndex]!
}

function resolveMarkdownItemHeight({
  estimateHeight,
  index,
  key,
  measuredHeights,
}: {
  estimateHeight: (index: number) => number
  index: number
  key: string
  measuredHeights: ReadonlyMap<string, number>
}) {
  return Math.max(1, measuredHeights.get(key) ?? estimateHeight(index))
}

function findFirstItemWithBottomAtOrAfter(
  offsets: readonly number[],
  target: number
) {
  let low = 0
  let high = Math.max(0, offsets.length - 1)

  while (low < high) {
    const middle = Math.floor((low + high) / 2)
    if (offsets[middle + 1]! >= target) {
      high = middle
    } else {
      low = middle + 1
    }
  }

  return low
}

function findFirstItemWithTopAfter(
  offsets: readonly number[],
  target: number
) {
  let low = 0
  let high = Math.max(0, offsets.length - 1)

  while (low < high) {
    const middle = Math.floor((low + high) / 2)
    if (offsets[middle]! > target) {
      high = middle
    } else {
      low = middle + 1
    }
  }

  return low
}
